import{_ as i,o as t,c as e,a3 as l}from"./chunks/framework.D1iekJsc.js";const k=JSON.parse('{"title":"开启局域网访问（Ollama）","description":"设置 OLLAMA_HOST=0.0.0.0 与防火墙，让手机 MiniTavern 通过局域网访问电脑上的 Ollama。","frontmatter":{"title":"开启局域网访问（Ollama）","description":"设置 OLLAMA_HOST=0.0.0.0 与防火墙，让手机 MiniTavern 通过局域网访问电脑上的 Ollama。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"开启局域网访问（Ollama） · MiniTavern Docs"}],["meta",{"property":"og:description","content":"设置 OLLAMA_HOST=0.0.0.0 与防火墙，让手机 MiniTavern 通过局域网访问电脑上的 Ollama。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ollama/lan"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ollama/lan"}]]},"headers":[],"relativePath":"ollama/lan.md","filePath":"ollama/lan.md","lastUpdated":1787117554000}'),s={name:"ollama/lan.md"};function n(o,a,r,h,p,d){return t(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="开启局域网访问-ollama" tabindex="-1">开启局域网访问（Ollama） <a class="header-anchor" href="#开启局域网访问-ollama" aria-label="Permalink to &quot;开启局域网访问（Ollama）&quot;">​</a></h1><p>默认情况下，Ollama 往往只监听本机。手机要连电脑，必须让服务监听 <strong>所有网卡</strong>（<code>0.0.0.0</code>），并放行防火墙端口。</p><h2 id="设置-ollama-host" tabindex="-1">设置 <code>OLLAMA_HOST</code> <a class="header-anchor" href="#设置-ollama-host" aria-label="Permalink to &quot;设置 `OLLAMA_HOST`&quot;">​</a></h2><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><ol><li>在开始菜单搜索「环境变量」→「编辑系统环境变量」→「环境变量」。</li><li>在「用户变量」或「系统变量」中新建：</li></ol><table tabindex="0"><thead><tr><th>变量名</th><th>变量值</th></tr></thead><tbody><tr><td><code>OLLAMA_HOST</code></td><td><code>0.0.0.0</code></td></tr></tbody></table><ol start="3"><li>确定保存后，<strong>完全退出并重新打开</strong> Ollama（托盘图标退出再启动）。</li></ol><p>也可在 PowerShell（当前会话临时生效）中：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OLLAMA_HOST </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;0.0.0.0&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 然后重启 ollama 应用或服务</span></span></code></pre></div><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><p>临时（当前终端会话）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">launchctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setenv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OLLAMA_HOST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span></span></code></pre></div><p>然后退出并重新打开 Ollama 应用。若重启后失效，可写入 shell 配置或使用 LaunchAgent；也可用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OLLAMA_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0.0.0</span></span></code></pre></div><p>并确保 Ollama 服务在该环境下启动。最稳妥仍是：<strong>设置环境变量后重启 Ollama</strong>。</p><h2 id="防火墙放行端口-11434" tabindex="-1">防火墙放行端口 11434 <a class="header-anchor" href="#防火墙放行端口-11434" aria-label="Permalink to &quot;防火墙放行端口 11434&quot;">​</a></h2><ul><li><strong>Windows</strong>：系统设置 → 隐私和安全性 → Windows 安全中心 → 防火墙 → 允许应用通过防火墙；或新建入站规则放行 TCP <code>11434</code>。</li><li><strong>macOS</strong>：系统设置 → 网络 → 防火墙；首次访问时允许 Ollama，或对端口放行。</li></ul><h2 id="验证局域网" tabindex="-1">验证局域网 <a class="header-anchor" href="#验证局域网" aria-label="Permalink to &quot;验证局域网&quot;">​</a></h2><ol><li>查电脑 IP（见 <a href="./../quickstart#step-4查电脑局域网-ip">快速开始 Step 4</a>）。</li><li>用<strong>同一 Wi‑Fi 下另一台设备</strong>的浏览器访问：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://YOUR_PC_IP:11434</span></span></code></pre></div><p>能打开或返回 Ollama 相关响应，说明局域网已通。</p><h2 id="给-minitavern-用的地址" tabindex="-1">给 MiniTavern 用的地址 <a class="header-anchor" href="#给-minitavern-用的地址" aria-label="Permalink to &quot;给 MiniTavern 用的地址&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://YOUR_PC_IP:11434/v1</span></span></code></pre></div><p>注意：</p><ul><li>用局域网 IP，<strong>不要</strong>用 <code>localhost</code></li><li>建议带 <code>/v1</code> 后缀（OpenAI 兼容路径）</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p><a href="./../connect-app/minitavern">在 MiniTavern 中配置</a></p>',27)])])}const m=i(s,[["render",n]]);export{k as __pageData,m as default};
